import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
for k,v in G.items(): print(k,len(v),len(v[0]))

from collections import Counter,deque
def shapes(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if (i,j) in seen or g[i][j]==0: pass
    # generic: shapes of non-background; background = most common color
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    for i in range(h):
        for j in range(w):
            if (i,j) not in seen and g[i][j]!=bg:
                c=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==c:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append((c,cells))
    return bg,out
def transform(g):
    bg,sh=shapes(g)
    colors=sorted(set(c for c,_ in sh))
    src=colors[0]  # smallest color
    tgt=colors[1] if len(colors)>1 else src
    src_shapes=[s for c,s in sh if c==src]
    big=max(src_shapes,key=len)
    g2=[r[:] for r in g]
    for y,x in big: g2[y][x]=tgt
    return g2
for p in (1,2):
    gi=G[f'Demo pair {p} input']; go=G[f'Demo pair {p} output']
    bg,sh=shapes(gi)
    print(p,'bg',bg,[ (c,len(s)) for c,s in sh])
    print(p,'match',transform(gi)==go)
